from PIL import Image
import colorsys
im = Image.open('barcode.png').convert('RGB')
w,h = im.size
cols = []
for x in range(w):
    rs=gs=bs=0
    for y in range(h):
        r,g,b = im.getpixel((x,y))
        rs+=r; gs+=g; bs+=b
    cols.append((rs/h, gs/h, bs/h))

def classify(r,g,b):
    hh,ll,ss = colorsys.rgb_to_hls(r/255,g/255,b/255)
    deg = hh*360
    if ss < 0.12: name='gray'
    elif deg < 20 or deg >= 340: name='red'
    elif deg < 45: name='orange/tan'
    elif deg < 70: name='yellow-olive'
    elif deg < 160: name='green'
    elif deg < 200: name='teal/cyan'
    elif deg < 260: name='blue'
    elif deg < 300: name='purple'
    else: name='pink/magenta'
    return name, ss, ll

print('saturated stripes (s>0.30), runs:')
out=[]
for i,(r,g,b) in enumerate(cols):
    n,s,l = classify(int(r),int(g),int(b))
    if s>0.30:
        hexc='#%02x%02x%02x'%(int(r),int(g),int(b))
        if out and i-out[-1][1]<=3 and n==out[-1][2]:
            out[-1][1]=i
        else:
            out.append([i,i,n,hexc])
for a,b2,n,hexc in out: print('x %3d-%3d  %-10s %s'%(a,b2,n,hexc))

print()
